import asyncioimport hashlibimport hmacimport jsonimport loggingimport osimport timeimport websocketslogging.basicConfig(    level=logging.INFO,    format="%(asctime)s  %(message)s",    handlers=[logging.FileHandler("bitmart_futures.log"), logging.StreamHandler()],)log = logging.getLogger()DEMO_TRADING = TruePROD_PUBLIC_WS = "wss://openapi-ws-v2.bitmart.com/api?protocol=1.1"PROD_PRIVATE_WS = "wss://openapi-ws-v2.bitmart.com/user?protocol=1.1"DEMO_PUBLIC_WS = "wss://openapi-wsdemo-v2.bitmart.com/api?protocol=1.1"DEMO_PRIVATE_WS = "wss://openapi-wsdemo-v2.bitmart.com/user?protocol=1.1"PUBLIC_WS_URL = DEMO_PUBLIC_WS if DEMO_TRADING else PROD_PUBLIC_WSPRIVATE_WS_URL = DEMO_PRIVATE_WS if DEMO_TRADING else PROD_PRIVATE_WSPING_INTERVAL_SEC = 15RECONNECT_BASE_DELAY_SEC = 3RECONNECT_MAX_DELAY_SEC = 60CONNECTIVITY_TEST_CHANNEL = "futures/ticker"def _load_db_config() -> dict:    here = os.path.dirname(os.path.abspath(__file__))    candidates = [        os.path.join(here, "db.txt"),        os.path.join(os.path.dirname(here), "db.txt"),    ]    for path in candidates:        if os.path.exists(path):            config = {}            with open(path, "r") as f:                for line in f:                    line = line.strip()                    if not line or line.startswith("#"):                        continue                    if "=" in line:                        k, _, v = line.partition("=")                        config[k.strip()] = v.strip().strip('"')            return config    raise FileNotFoundError(f"db.txt not found in any of: {candidates}")def _clean_secret(value):    if value is None:        return None    if isinstance(value, str):        value = value.strip()        if value.upper() in ("", "NULL"):            return None    return valuedef load_bitmart_credentials() -> dict:    from supabase import create_client    config = _load_db_config()    sb = create_client(config["SUPABASE_URL"], config["SUPABASE_KEY"])    rows = sb.table("api_keys").select("*").execute()    match = next(        (r for r in rows.data or [] if (r.get("exchange_name") or "").strip().lower() == "bitmart"),        None,    )    if not match:        raise RuntimeError("No 'BitMart' row found in the api_keys Supabase table")    api_key = _clean_secret(match.get("api_key"))    api_secret = _clean_secret(match.get("api_secret"))    memo_uid = _clean_secret(match.get("uid"))    memo_passphrase = _clean_secret(match.get("passphrase"))    if not api_key or not api_secret:        missing = [n for n, v in (("api_key", api_key), ("api_secret", api_secret)) if not v]        raise RuntimeError(f"BitMart credentials incomplete in Supabase — missing: {', '.join(missing)}")    memo_candidates = []    for m in (memo_uid, memo_passphrase):        if m and m not in memo_candidates:            memo_candidates.append(m)    if not memo_candidates:        raise RuntimeError("BitMart credentials incomplete in Supabase — missing memo (uid or passphrase column)")    return {"api_key": api_key, "api_secret": api_secret, "memo_candidates": memo_candidates}def build_login_sign(timestamp_ms: str, memo: str, api_secret: str) -> str:    payload = f"{timestamp_ms}#{memo}#bitmart.WebSocket"    return hmac.new(api_secret.encode(), payload.encode(), hashlib.sha256).hexdigest()async def _keepalive(ws):    while True:        await asyncio.sleep(PING_INTERVAL_SEC)        try:            await ws.send(json.dumps({"action": "ping"}))        except Exception:            returnasync def run_public():    delay = RECONNECT_BASE_DELAY_SEC    while True:        try:            log.info(f"[public] connecting to {PUBLIC_WS_URL}")            async with websockets.connect(PUBLIC_WS_URL, ping_interval=None) as ws:                log.info("[public] connected")                delay = RECONNECT_BASE_DELAY_SEC                await ws.send(json.dumps({"action": "subscribe", "args": [CONNECTIVITY_TEST_CHANNEL]}))                keepalive_task = asyncio.create_task(_keepalive(ws))                try:                    async for raw in ws:                        if raw == "pong":                            continue                        try:                            msg = json.loads(raw)                        except json.JSONDecodeError:                            log.warning(f"[public] non-JSON message: {raw[:200]}")                            continue                        if msg.get("action") == "subscribe":                            if msg.get("success"):                                log.info(f"[public] \u2705 subscribed to {msg.get('group')}")                            else:                                log.error(f"[public] \u274c subscribe failed: {msg}")                        elif "group" in msg:                            log.info(f"[public] data: {msg.get('group')} -> {json.dumps(msg.get('data'))[:200]}")                        else:                            log.info(f"[public] message: {msg}")                finally:                    keepalive_task.cancel()        except Exception as e:            log.error(f"[public] connection error: {type(e).__name__}: {str(e)[:200]} \u2014 reconnecting in {delay}s")            await asyncio.sleep(delay)            delay = min(delay * 2, RECONNECT_MAX_DELAY_SEC)async def run_private(creds: dict):    delay = RECONNECT_BASE_DELAY_SEC    memo_candidates = creds["memo_candidates"]    memo_index = 0    while True:        memo = memo_candidates[memo_index]        try:            log.info(f"[private] connecting to {PRIVATE_WS_URL}")            async with websockets.connect(PRIVATE_WS_URL, ping_interval=None) as ws:                log.info("[private] connected \u2014 logging in")                delay = RECONNECT_BASE_DELAY_SEC                timestamp_ms = str(int(time.time() * 1000))                sign = build_login_sign(timestamp_ms, memo, creds["api_secret"])                login_msg = {"action": "access", "args": [creds["api_key"], timestamp_ms, sign, "web"]}                await ws.send(json.dumps(login_msg))                keepalive_task = asyncio.create_task(_keepalive(ws))                try:                    async for raw in ws:                        if raw == "pong":                            continue                        try:                            msg = json.loads(raw)                        except json.JSONDecodeError:                            log.warning(f"[private] non-JSON message: {raw[:200]}")                            continue                        if msg.get("action") == "access":                            if msg.get("success"):                                log.info("[private] \u2705 login successful")                            else:                                error = str(msg.get("error", ""))                                log.error(f"[private] \u274c login failed: {msg}")                                if "sign" in error.lower() and memo_index + 1 < len(memo_candidates):                                    memo_index += 1                                    log.error("[private] retrying login with alternate memo source")                                    raise ConnectionError("retrying with alternate memo")                                await asyncio.sleep(RECONNECT_MAX_DELAY_SEC)                        else:                            log.info(f"[private] message: {msg}")                finally:                    keepalive_task.cancel()        except Exception as e:            log.error(f"[private] connection error: {type(e).__name__}: {str(e)[:200]} \u2014 reconnecting in {delay}s")            await asyncio.sleep(delay)            delay = min(delay * 2, RECONNECT_MAX_DELAY_SEC)async def main():    creds = load_bitmart_credentials()    log.info(f"Starting BitMart Futures WS connectivity check (demo_trading={DEMO_TRADING})")    await asyncio.gather(        run_public(),        run_private(creds),    )if __name__ == "__main__":    try:        asyncio.run(main())    except KeyboardInterrupt:        log.info("bitmart_futures.py stopped.")